import base64,hashlib,zlib
PAYLOAD="",
raw=zlib.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(raw).hexdigest()=="59d4a2635b5a64de32a1fd69c577c123fab1fe81bb1739a632ec7035dc5b4f5b", "frozen calibration payload checksum mismatch"
exec(compile(raw.decode(),"taccola_calibration.py","exec"))
